Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchText(text = "Request #1042 · Billing question", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted, modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center)
    MonarchText(text = "How would you rate the support you received?", style = MonarchTextStyle.Heading, modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center)
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        listOf("Good", "Bad").forEachIndexed { index, choice ->
            val selected = answer == choice
            val shape = MonarchTheme.shapes.md
            Column(
                modifier = Modifier
                    .weight(1f)
                    .clip(shape)
                    .background(if (selected) MonarchTheme.colors.accentSubtle else MonarchTheme.colors.bgSurface)
                    .border(1.dp, if (selected) MonarchTheme.colors.accentBorder else MonarchTheme.colors.borderDefault, shape)
                    .selectable(
                        selected = selected,
                        role = Role.RadioButton,
                        onClick = {
                            answer = choice
                            status = MonarchSaveStatus.Saving // the app saves, then sets Saved or Error
                        },
                    )
                    .padding(vertical = MonarchTheme.spacing.space4),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
            ) {
                MonarchIcon(
                    imageVector = if (index == 0) SampleIcons.ThumbUp else SampleIcons.ThumbDown,
                    contentDescription = null,
                )
                MonarchText(text = choice, style = MonarchTextStyle.BodyStrong)
            }
        }
    }
    if (answer == null) {
        MonarchText(text = "Choose an answer above. You can add a comment afterwards.", modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center, color = MonarchTheme.colors.textMuted)
    } else {
        MonarchTextField(
            value = comment,
            onValueChange = { comment = it.take(500) },
            label = "Anything you would like to add? (optional)",
            helperText = "${500 - comment.length} characters left",
            singleLine = false,
        )
        MonarchButton(text = "Save comment", onClick = { status = MonarchSaveStatus.Saving })
    }
    MonarchSaveStatusIndicator(status = status, onRetry = { status = MonarchSaveStatus.Saving })
}

if (loading) {
    MonarchLoadingState(label = "Loading survey", variant = MonarchLoadingStateVariant.Spinner)
} else {
    MonarchErrorState(
        title = "We could not load this survey",
        kind = MonarchErrorStateKind.NotFound,
        message = "This link has expired. Ask the team for a new one.",
    )
}
